/// <summary>Events interface for Microsoft Excel <see cref="T:Microsoft.Office.Interop.Excel.Application"></see> object events.</summary>
[TypeLibType(16)]
[ComVisible(false)]
[ComEventInterface(typeof(AppEvents\u0000), typeof(AppEvents_EventProvider\u0000))]
public interface AppEvents_Event
{
	/// <summary>Occurs when a new workbook is created.</summary>
	event AppEvents_NewWorkbookEventHandler NewWorkbook;

	/// <summary>Occurs when the selection changes on any worksheet (doesn't occur if the selection is on a chart sheet).</summary>
	event AppEvents_SheetSelectionChangeEventHandler SheetSelectionChange;

	/// <summary>Occurs when any worksheet is double-clicked, before the default double-click action.</summary>
	event AppEvents_SheetBeforeDoubleClickEventHandler SheetBeforeDoubleClick;

	/// <summary>Occurs when any worksheet is right-clicked, before the default right-click action.</summary>
	event AppEvents_SheetBeforeRightClickEventHandler SheetBeforeRightClick;

	/// <summary>Occurs when any sheet is activated.</summary>
	event AppEvents_SheetActivateEventHandler SheetActivate;

	/// <summary>Occurs when any sheet is deactivated.</summary>
	event AppEvents_SheetDeactivateEventHandler SheetDeactivate;

	/// <summary>Occurs after any worksheet is recalculated or after any changed data is plotted on a chart.</summary>
	event AppEvents_SheetCalculateEventHandler SheetCalculate;

	/// <summary>Occurs when cells in any worksheet are changed by the user or by an external link.</summary>
	event AppEvents_SheetChangeEventHandler SheetChange;

	/// <summary>Occurs when a workbook is opened.</summary>
	event AppEvents_WorkbookOpenEventHandler WorkbookOpen;

	/// <summary>Occurs when any workbook is activated.</summary>
	event AppEvents_WorkbookActivateEventHandler WorkbookActivate;

	/// <summary>Occurs when any open workbook is deactivated.</summary>
	event AppEvents_WorkbookDeactivateEventHandler WorkbookDeactivate;

	/// <summary>Occurs immediately before any open workbook closes.</summary>
	event AppEvents_WorkbookBeforeCloseEventHandler WorkbookBeforeClose;

	/// <summary>Occurs before any open workbook is saved.</summary>
	event AppEvents_WorkbookBeforeSaveEventHandler WorkbookBeforeSave;

	/// <summary>Occurs before any open workbook is printed.</summary>
	event AppEvents_WorkbookBeforePrintEventHandler WorkbookBeforePrint;

	/// <summary>Occurs when a new sheet is created in any open workbook.</summary>
	event AppEvents_WorkbookNewSheetEventHandler WorkbookNewSheet;

	/// <summary>Occurs when a workbook is installed as an add-in.</summary>
	event AppEvents_WorkbookAddinInstallEventHandler WorkbookAddinInstall;

	/// <summary>Occurs when any add-in workbook is uninstalled.</summary>
	event AppEvents_WorkbookAddinUninstallEventHandler WorkbookAddinUninstall;

	/// <summary>Occurs when any workbook window is resized.</summary>
	event AppEvents_WindowResizeEventHandler WindowResize;

	/// <summary>Occurs when any workbook window is activated.</summary>
	event AppEvents_WindowActivateEventHandler WindowActivate;

	/// <summary>Occurs when any workbook window is deactivated.</summary>
	event AppEvents_WindowDeactivateEventHandler WindowDeactivate;

	/// <summary>Occurs when you click any hyperlink in Microsoft Excel.</summary>
	event AppEvents_SheetFollowHyperlinkEventHandler SheetFollowHyperlink;

	/// <summary>Occurs after the sheet of the PivotTable report has been updated.</summary>
	event AppEvents_SheetPivotTableUpdateEventHandler SheetPivotTableUpdate;

	/// <summary>Occurs after a PivotTable report connection has been closed.</summary>
	event AppEvents_WorkbookPivotTableCloseConnectionEventHandler WorkbookPivotTableCloseConnection;

	/// <summary>Occurs after a <see cref="T:Microsoft.Office.Interop.Excel.PivotTable"></see>report connection has been opened.</summary>
	event AppEvents_WorkbookPivotTableOpenConnectionEventHandler WorkbookPivotTableOpenConnection;

	/// <summary>Occurs when the local copy of a workbook that is part of a Document Workspace is synchronized with the copy on the server.</summary>
	event AppEvents_WorkbookSyncEventHandler WorkbookSync;

	/// <summary>Occurs before an existing XML data connection is refreshed or new XML data is imported into any open Microsoft Excel workbook.</summary>
	event AppEvents_WorkbookBeforeXmlImportEventHandler WorkbookBeforeXmlImport;

	/// <summary>Occurs after an existing XML data connection is refreshed or new XML data is imported into any open Microsoft Excel workbook.</summary>
	event AppEvents_WorkbookAfterXmlImportEventHandler WorkbookAfterXmlImport;

	/// <summary>Occurs before Microsoft Excel saves or exports data from any open workbook to an XML data file.</summary>
	event AppEvents_WorkbookBeforeXmlExportEventHandler WorkbookBeforeXmlExport;

	/// <summary>Occurs after Microsoft Excel saves or exports data from any open workbook to an XML data file.</summary>
	event AppEvents_WorkbookAfterXmlExportEventHandler WorkbookAfterXmlExport;

	/// <summary>The <see cref="E:Microsoft.Office.Interop.Excel.AppEvents_Event.WorkbookRowsetComplete"></see>event  occurs when the user either drills through the recordset or invokes the rowset action on an OLAP PivotTable.</summary>
	/// <param name="Success">Contains a Boolean value to indicate success or failure.</param>
	/// <param name="Sheet">The worksheet on which the recordset is created.</param>
	/// <param name="Wb">The workbook for which the event occurs.</param>
	/// <param name="Description">A brief description of the event.</param>
	event AppEvents_WorkbookRowsetCompleteEventHandler WorkbookRowsetComplete;

	/// <summary>The <see cref="E:Microsoft.Office.Interop.Excel.ApplicationClass.AfterCalculate"></see> event occurs when all pending refresh activity (both synchronous and asynchronous) and all of the resultant calculation activities have been completed.</summary>
	event AppEvents_AfterCalculateEventHandler AfterCalculate;
}
